  "inlineSchema": "// Prisma schema for Office Manager (OM) Weekly Report Management System\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// User / Office Manager (OM) or Admin\nmodel User {\n  id          String   @id @default(cuid())\n  staffId     String   @unique // e.g. \"572816\", \"451467\", \"362578\"\n  name        String // e.g. \"Md. Benajir Alam\"\n  designation String // e.g. \"TE\", \"Jex\", \"Area Manager\"\n  zone        String // e.g. \"D.M-01/Mitford\", \"Comilla\", \"Cox's Bazar\"\n  email       String   @unique\n  mobile      String?\n  role        String   @default(\"OM\") // \"OM\" | \"ADMIN\"\n  status      String   @default(\"ACTIVE\") // \"ACTIVE\" | \"INACTIVE\"\n  password    String? // Optional password/PIN\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  reports       WeeklyReport[]\n  targets       MonthlyTarget[]\n  findingAudits FindingHistory[]       @relation(\"UpdatedByAudits\")\n  emailLogs     EmailNotificationLog[]\n\n  @@index([zone])\n  @@index([status])\n  @@index([role])\n}\n\n// Zone Master Table\nmodel Zone {\n  id        String   @id @default(cuid())\n  name      String   @unique // e.g. \"D.M-01/Mitford\", \"Comilla\"\n  code      String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n}\n\n// Weekly Report submitted by OM\nmodel WeeklyReport {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  monthYear String // Display label: \"September 2026\", \"October 2026\"\n  year      Int // 2026\n  month     Int // 1 - 12 (e.g. 9)\n  week      Int // 1, 2, 3, 4\n\n  // 1. Market Visit\n  marketVisitQty        Int @default(0)\n  marketVisitFindingQty Int @default(0)\n  solvedQty             Int @default(0)\n  pendingQty            Int @default(0)\n\n  // 2. Location Tracking (LOC) - STRICTLY NO \"LOC Visit Qty\" field\n  locSubmittedQty  Int   @default(0)\n  locFindingDayQty Float @default(0.0) // Can be float e.g. 3.5 days\n\n  // 3. Dress Code\n  dressCodeQty        Int @default(0)\n  dressCodeFindingQty Int @default(0)\n\n  // 4. Mess Visit\n  messVisitQty        Int @default(0)\n  messVisitFindingQty Int @default(0)\n\n  // Status: SUBMITTED | PENDING | LATE_SUBMITTED\n  status      String   @default(\"SUBMITTED\")\n  deadline    DateTime // Friday 11:59:59 PM of that week\n  submittedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  notes       String?\n\n  findingHistory FindingHistory[]\n\n  @@unique([userId, year, month, week])\n  @@index([year, month, week])\n  @@index([userId])\n  @@index([status])\n}\n\n// Audit history for Market Visit Finding status updates\nmodel FindingHistory {\n  id       String       @id @default(cuid())\n  reportId String\n  report   WeeklyReport @relation(fields: [reportId], references: [id], onDelete: Cascade)\n\n  updatedById String\n  updatedBy   User   @relation(\"UpdatedByAudits\", fields: [updatedById], references: [id])\n\n  previousSolved  Int\n  newSolved       Int\n  previousPending Int\n  newPending      Int\n  remark          String?\n  createdAt       DateTime @default(now())\n\n  @@index([reportId])\n}\n\n// Monthly Target set by Admin for each OM\nmodel MonthlyTarget {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  year      Int // 2026\n  month     Int // 1 - 12\n  monthYear String // e.g. \"September 2026\"\n\n  locTarget       Int @default(0) // LOC Submitted Qty Target\n  messVisitTarget Int @default(0) // Mess Visit Qty Target\n  dressCodeTarget Int @default(0) // Dress Code Qty Target\n\n  isLocked  Boolean  @default(false) // Locked/Approved flag to protect historical calculations\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, year, month])\n  @@index([year, month])\n}\n\n// Admin-configurable Email Notification Rules\nmodel EmailNotificationConfig {\n  id              String   @id @default(cuid())\n  code            String   @unique // e.g. \"WEEKLY_DEADLINE_MISSED\"\n  name            String // e.g. \"Missed Weekly Report Reminder\"\n  description     String?\n  subjectTemplate String // e.g. \"[URGENT] Missed Weekly Report - {OM_NAME} ({MONTH} Week {WEEK})\"\n  bodyTemplate    String // Template with placeholders\n  ccRecipients    String // Comma-separated emails for Seniors / Reporting Bosses\n  bccRecipients   String?\n  isActive        Boolean  @default(true)\n  updatedAt       DateTime @updatedAt\n}\n\n// Email Notification History to prevent duplicate spamming\nmodel EmailNotificationLog {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  year         Int\n  month        Int\n  week         Int\n  emailType    String // \"MISSED_DEADLINE\"\n  toEmail      String\n  ccEmails     String?\n  subject      String\n  status       String   @default(\"SENT\") // \"SENT\" | \"FAILED\"\n  sentAt       DateTime @default(now())\n  errorMessage String?\n\n  @@unique([userId, year, month, week, emailType])\n  @@index([year, month, week])\n}\n",
